import {
    exporter,
    library,
    metadata,
    operations,
    collections,
    shelves,
    tagging,
} from '../wailsjs/go/models';

onClick={() => setCollapsedTagFacets((current) => {
                    const next = new Set(current);
                    if (next.has(definition.id)) next.delete(definition.id);
                    else next.add(definition.id);
                    return next;
                })}

onClick={() => {
                                        const ids = curatedShelves.map((entry) => entry.id);
                                        [ids[index], ids[index + delta]] = [ids[index + delta], ids[index]];
                                        setCollectionBusy(true);
                                        void ReorderShelves(ids).then((response) => {if (response.error) setRequestError(response.error.message); else setShelfRevision((value) => value + 1);})
                                            .catch(() => setRequestError(t('Shelves could not be reordered.'))).finally(() => setCollectionBusy(false));
                                    }}

onChange={(event) => updateQuery({
                                    ...collectionQuery,
                                    sort: event.currentTarget.value as CollectionQuery['sort'],
                                    page: 1,
                                })}

onClick={() => {
                                updateQuery({
                                    ...collectionQuery,
                                    name: '',
                                    anyOf: undefined,
                                    brokenState: undefined,
                                    languages: [],
                                    compatibilities: [],
                                    booleanFilters: [],
                                    choiceFilters: [],
                                    page: 1,
                                });
                                searchInput.current?.focus();
                            }}

onClick={() => row.collectionID === undefined
                                    ? void loadAllStories()
                                    : void openSavedCollection(row.collectionID)}

onClick={(event) => {
                                            if (event.ctrlKey || event.metaKey || event.shiftKey) {
                                                const next = selectedIDs.includes(story.id)
                                                    ? selectedIDs.length === 1
                                                        ? selectedIDs
                                                        : selectedIDs.filter((storyID) => storyID !== story.id)
                                                    : [...selectedIDs, story.id];
                                                setSelectedIDs(next);
                                                setSelectedID(next.includes(story.id) ? story.id : next[0]);
                                            } else {
                                                setSelectedIDs([story.id]);
                                                setSelectedID(story.id);
                                            }
                                        }}

onClick={() => {
                                setRemovalError(null);
                                setInspectedStory(selected);
                                setInspectedArchive(detail?.story.id === selected.id ? detail.archive : undefined);
                                setDetailsOpen(true);
                            }}

onClose={() => {
                        flags.dismissFeedback();
                        setDetailsOpen(false);
                        setInspectedStory(null);
                        setInspectedArchive(undefined);
                        openDetailsButton.current?.focus({preventScroll: true});
                    }}

onClick={() => {
                            setCollectionBusy(true);
                            void AddStoriesToShelf(Number(addShelfID), renderedStories.filter((story) => selectedIDs.includes(story.id)).map((story) => story.uuid)).then((response) => {
                                if (response.error) setRequestError(response.error.message); else {setShelfRevision((value) => value + 1); setAddShelfOpen(false);}
                            }).catch(() => setRequestError(t('Shelf could not be changed.'))).finally(() => setCollectionBusy(false));
                        }}

onClose={() => {
                        if (selectedID === null || !tagAssignmentStoryIDs.includes(selectedID)) {
                            setDetailsOpen(false);
                            openDetailsButton.current?.focus({preventScroll: true});
                        }
                        setTagAssignmentOpen(false);
                        setTagAssignmentStoryIDs([]);
                    }}

onClick={(event) => {
                if (event.target === event.currentTarget && startedOutside.current && !disabled) {
                    event.stopPropagation();
                    onDismiss();
                }
            }}

history.map((operation) => (
                        <details className="history-entry" key={operation.id}>
                            <summary>
                                <span className="history-kind">{t(kindLabels[operation.kind] ?? operation.kind)}</span>
                                <span className={`history-status ${operation.status}`}>
                                    {t(statusLabels[operation.status] ?? operation.status)}
                                </span>
                                <time dateTime={operation.createdAt}>
                                    {new Date(operation.createdAt).toLocaleString(currentLanguage())}
                                </time>
                            </summary>
                            <div className="history-detail">
                                <p>{operation.completedItems} {' ' + t("of") + ' '}{operation.totalItems} {' ' + t("items finished.")}</p>
                                {operation.errorMessage && <p>{<OutcomeText text={operation.errorMessage} status={operation.status}/>}</p>}
                                {operation.kind === 'export' && operationIsTerminal(operation) ? (
                                    <ExportReport operation={operation} onReveal={(operationID) => {
                                        setRevealError(null);
                                        void onReveal(operationID).then(setRevealError);
                                    }}/>
                                ) : (
                                    <ul className="operation-items">
                                        {operation.items.map((item) => (
                                            <li key={item.id}>
                                                <b>{item.storyTitle || item.sourceName}</b>
                                                <span>{<OutcomeText text={item.outcomeMessage || statusLabels[item.status] || item.status} status={item.status}/>}</span>
                                            </li>
                                        ))}
                                    </ul>
                                )}
                            </div>
                        </details>
                    ))

onChange={(event) => {
            const text = event.currentTarget.value;
            setDraft({text, canonical: normalizeSearchText(text)});
            onChange(text);
        }}

onClick={() => {
  setWorking(true); setError('');
  void ConfirmLibrarySetup().then(async (result) => {
   if (result.error) { setError(result.error.message); return; }
   if (!result.success) { setError('settings.invalid'); return; }
   accept(await Settings()); setOpen(false); onReady();
  }).catch(() => setError('settings.invalid')).finally(() => setWorking(false));
 }}

onClick={() => void act(async () => {
                const result = dialog === 'rename' ? await RenameShelf(id, name) : dialog === 'duplicate' ? await DuplicateShelf(id, name) : await DeleteShelf(id);
                if (!result.error) {setDialog(null); if (dialog === 'delete') onDeleted();} return result;
            })}

onChange={(checked) => void apply(() => (
                                            SetBooleanTag(storyIDs, definition.id, checked)
                                        ))}

onSubmit={(event) => {
                                        event.preventDefault();
                                        const color = String(new FormData(event.currentTarget).get('color'));
                                        if (color.toUpperCase() !== definition.color.toUpperCase()) {
                                            void run(() => RecolorTagDefinition(definition.id, color));
                                        }
                                    }}

window.history.replaceState({
            collectionQuery: {
                hash,
                collectionId: null,
                scope: 'all',
            },
        }, '', `${window.location.pathname}${window.location.search}${hash}`)
